    local directEnvironmentValues = {
        http = directHttp,
        request = directRequest,
        http_request = directHttpRequest,
        gethwid = directGetHwid,
        get_hwid = directGetHwidAlt,
        identifyexecutor = directIdentifyExecutor,
        getexecutorname = directGetExecutorName,
        syn = directSyn,
